from glom.core import glom

target = {
    'user': {'profile': {'name': 'Ada', 'city': 'Paris'}, 'scores': [2, 5, 7]},
    'meta': {'active': True, 'count': 3},
    'archive': {'user': {'profile': {'name': 'Old'}, 'scores': [100]}}
}
spec = {'name': 'user.profile.name', 'city': 'user.profile.city', 'scores': ('user.scores', [lambda x: x + 1])}
result = glom(target, spec)
result['total'] = sum(result['scores'])

print(result)
print(result['scores'][1:])
print(result['name'] + '@' + result['city'])
